def degree(vertex, edges):
    return sum(1 for (u, v) in edges if u == vertex or v == vertex)

edges = {("A", "B"), ("A", "E"), ("A", "F"), ("B", "C"), ("B", "F")}
print(degree("A", edges))  # 3: connects to B, E, and F
print(degree("B", edges))  # 3: connects to A, C, and F

def in_out_degree(vertex, directed_edges):
    in_deg = sum(1 for (u, v) in directed_edges if v == vertex)
    out_deg = sum(1 for (u, v) in directed_edges if u == vertex)
    return in_deg, out_deg

def path_exists(start, end, edges):
    from collections import deque
    adjacency = {}
    for (u, v) in edges:
        adjacency.setdefault(u, []).append(v)
        adjacency.setdefault(v, []).append(u)

    visited = {start}
    queue = deque([start])
    while queue:
        current = queue.popleft()
        if current == end:
            return True
        for neighbor in adjacency.get(current, []):
            if neighbor not in visited:
                visited.add(neighbor)
                queue.append(neighbor)
    return False

edges = {("A", "B"), ("B", "C"), ("D", "E")}
print(path_exists("A", "C", edges))  # True, via B
print(path_exists("A", "D", edges))  # False, no connecting edge at all

